import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { listJobs } from "../services/api";

export default function HMDashboard() {
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);

  useEffect(() => {
    listJobs().then(r => {
      const seen = new Map();
      r.data.forEach(j => {
        if (!seen.has(j.title) || j.id > seen.get(j.title).id) {
          seen.set(j.title, j);
        }
      });
      setJobs(Array.from(seen.values()));
    }).catch(() => {});
  }, []);

  return (
    <div style={{ animation: "fadeUp 0.5s ease" }}>
      <div style={{ marginBottom: 40 }}>
        <div className="badge badge-teal" style={{ marginBottom: 16 }}>Hiring Manager</div>
        <h1 style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 800, fontSize: 36, color: "var(--text-primary)", marginBottom: 8 }}>
          Candidate Shortlists
        </h1>
        <p style={{ color: "var(--text-secondary)", fontSize: 16 }}>
          Review and approve shortlisted candidates for each open position.
        </p>
      </div>

      {jobs.length === 0 ? (
        <div className="card" style={{ padding: 60, textAlign: "center" }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>📋</div>
          <div style={{ fontFamily: "Plus Jakarta Sans", fontSize: 18, color: "var(--text-primary)", marginBottom: 8 }}>
            No positions yet
          </div>
          <div style={{ color: "var(--text-secondary)", fontSize: 14 }}>
            A recruiter needs to create a job and shortlist candidates first.
          </div>
        </div>
      ) : (
        <div style={{ display: "grid", gap: 16, gridTemplateColumns: "repeat(auto-fill, minmax(320px, 1fr))" }}>
          {jobs.map((j, i) => (
            <div key={j.id} className="card" style={{
              padding: 28,
              animation: `fadeUp 0.4s ease ${i * 0.08}s both`,
              cursor: "pointer",
              transition: "all 0.2s",
            }}
            onClick={() => navigate(`/hm-review/${j.id}`)}
            onMouseEnter={e => {
              e.currentTarget.style.borderColor = "rgba(20,184,166,0.4)";
              e.currentTarget.style.transform = "translateY(-2px)";
            }}
            onMouseLeave={e => {
              e.currentTarget.style.borderColor = "var(--border)";
              e.currentTarget.style.transform = "translateY(0)";
            }}>
              {/* Job title + industry */}
              <div style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 18, color: "var(--text-primary)", marginBottom: 6 }}>
                {j.title}
              </div>
              <div style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 6 }}>
                {j.industry && <span>{j.industry}</span>}
                {j.min_experience > 0 && <span> · {j.min_experience}+ years exp</span>}
              </div>
              <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 24, lineHeight: 1.5 }}>
                {j.required_skills?.slice(0, 80)}...
              </div>

              {/* Primary action — Review Shortlist */}
              <button className="btn-primary" style={{ width: "100%", padding: "12px", fontSize: 14, marginBottom: 8 }}
                onClick={e => { e.stopPropagation(); navigate(`/hm-review/${j.id}`); }}>
                Review Shortlist →
              </button>

              {/* Secondary action — See all results (smaller, less prominent) */}
              <button className="btn-secondary" style={{ width: "100%", padding: "8px", fontSize: 12 }}
                onClick={e => { e.stopPropagation(); navigate(`/results/${j.id}`); }}>
                View all candidates
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
